   finally{ for(i=0;i<ks.length;i++){ var k3=ks[i]; if(keep[k3]===undefined) delete P[k3]; else P[k3]=keep[k3]; } try{ saveProfile(); }catch(_sp){} }
   return bad.length?bad.join('; '):null; }},
